/// Local product text keeps its resource key and captured arguments until display.
/// Raw daemon, CLI, user and OS text remains byte-for-byte as received.
public struct LocalizedMessage: Equatable, Sendable {
    fileprivate enum Argument: Equatable, Sendable {
        case string(String), integer(Int64), number(Double)
        var value: CVarArg {
            switch self { case .string(let v): v; case .integer(let v): v; case .number(let v): v }
        }
    }
    fileprivate var key: String?
    fileprivate var arguments: [Argument] = []
    private var raw: String = ""
    fileprivate init(key: String, arguments: [Argument]) { self.key = key; self.arguments = arguments }
    public init(raw: String) { self.raw = raw }
    // Stable resource identity for local semantic error mapping; never rendered text.
    var resourceKey: String? { key }
    var rawText: String? { key == nil ? raw : nil }
    public func resolve(locale: String = MessageLocale.current) -> String {
        guard let key else { return raw }
        return L10n.format(key, locale: locale, args: arguments.map(\.value))
    }
}

public enum MessageLocale {
    /// Batch extraction keeps production Chinese. Tests may scope a locale;
    /// sample-data launches can opt in without changing saved preferences.
    @TaskLocal public static var overrideForTesting: String?
    public static var current: String {
        if let overrideForTesting { return resolve(overrideForTesting, system: []) }
        #if DEBUG
        let args = ProcessInfo.processInfo.arguments
        if (args.contains("-demo") || args.contains("-gallery")),
           let index = args.firstIndex(of: "-messageLocale"), index + 1 < args.count {
            return resolve(args[index + 1], system: [])
        }
        #endif
        return "zh-CN"
    }

    public static let appleTags: [String: String] = ["zh-CN": "zh-Hans", "en": "en"]
    private static let languages: [String: String] = ["zh": "zh-CN", "en": "en"]
    public static func resolve(_ preference: String = "auto", system: [String] = Locale.preferredLanguages) -> String {
        if appleTags[preference] != nil { return preference }
        for tag in system {
            let base = tag.replacingOccurrences(of: "_", with: "-").lowercased()
                .components(separatedBy: ".")[0].components(separatedBy: "@")[0]
                .components(separatedBy: "-")[0]
            if let language = languages[base] { return language }
        }
        return "zh-CN"
    }
}
